using UnityEngine;
public sealed class VlabSpring:MonoBehaviour{
 [SerializeField] MeshFilter coil;[SerializeField] Transform bottomHook,topContact,bottomContact;[SerializeField] BoxCollider pick;Mesh mesh;Vector2[] uv;Vector3[] vertices,normals;
 public const float WireRadius=.0008f;public const float CoilRadius=.010f;public float LengthM{get;private set;}=.15f;public Vector3 Top=>topContact.position;public Vector3 Bottom=>bottomContact.position;
 Vector3 Point(Vector3 s)=>coil.transform.InverseTransformPoint(transform.TransformPoint(new Vector3(s.x,s.y,-s.z)));
 Vector3 Normal(Vector3 s)=>coil.transform.InverseTransformDirection(transform.TransformDirection(new Vector3(s.x,s.y,-s.z))).normalized;
 void Awake(){mesh=Instantiate(coil.sharedMesh);mesh.name="Runtime UV-driven Blender spring";mesh.MarkDynamic();coil.sharedMesh=mesh;uv=mesh.uv;vertices=mesh.vertices;normals=new Vector3[vertices.Length];TrySetEndpoints(Top,Bottom);}
 public bool TrySetEndpoints(Vector3 a,Vector3 b){var delta=b-a;float length=delta.magnitude;if(!isActiveAndEnabled||!mesh||!float.IsFinite(a.sqrMagnitude)||!float.IsFinite(b.sqrMagnitude)||!float.IsFinite(length)||length<.099999f||length>.200001f||(transform.lossyScale-Vector3.one).sqrMagnitude>1e-10f)return false;length=Mathf.Clamp(length,.1f,.2f);var down=transform.TransformDirection(Vector3.forward);transform.rotation=Quaternion.FromToRotation(down,delta.normalized)*transform.rotation;transform.position=a;bottomHook.localPosition=Vector3.forward*length;for(int i=0;i<vertices.Length;i++){float t=uv[i].x*12*Mathf.PI*2,phi=uv[i].y*Mathf.PI*2;var u=new Vector3(Mathf.Cos(t),Mathf.Sin(t),0);var tangent=new Vector3(-CoilRadius*Mathf.Sin(t),CoilRadius*Mathf.Cos(t),-(length-.030f)/(12*Mathf.PI*2)).normalized;var w=Vector3.Cross(tangent,u).normalized;var n=u*Mathf.Cos(phi)+w*Mathf.Sin(phi);var center=new Vector3(CoilRadius*Mathf.Cos(t),CoilRadius*Mathf.Sin(t),-.015f-(length-.030f)*uv[i].x);vertices[i]=Point(center+WireRadius*n);normals[i]=Normal(n);}mesh.vertices=vertices;mesh.normals=normals;mesh.RecalculateBounds();pick.center=Vector3.forward*(length*.5f);pick.size=new Vector3(.022f,.022f,length+.004f);LengthM=length;return true;}
 void OnDestroy(){if(mesh)Destroy(mesh);}
 // shortcut: prescribed100..200mm endpoints,1um endpoint tolerance and fixed wire/hook geometry; force law, damping, contact and calibration belong to the assembled lesson.
}
